using FluentAssertions;
using Newtonsoft.Json;
using NUnit.Framework;
using SWLOR.Game.Server.Entity;
using SWLOR.Game.Server.Extension;
using SWLOR.Game.Server.Feature.ShipRewardDefinition;
using SWLOR.Game.Server.Service.AchievementService;
using SWLOR.Game.Server.Service.SpaceService;

namespace SWLOR.Game.Server.Tests.Service;

/// <summary>
/// The space achievements (plan section 14): first kill per faction tier, a capital kill, each ace, a named module, the
/// first jump to each kind of scanned site, Wild Space and trade earnings. Generated by tools/SpaceRevampBalance/rewards.py.
/// </summary>
public class SpaceAchievementTests
{
    private static readonly AchievementType[] Space = Enum.GetValues<AchievementType>().Where(x => (int)x >= 187).ToArray();

    [Test]
    public void SpaceAchievements_FollowTheGroundOnesAndAreActive()
    {
        Space.Select(x => (int)x).Should().BeEquivalentTo(Enumerable.Range(187, Space.Length), "numbered after Final Salvo (186)");
        Space.Length.Should().Be(6 + 1 + RevampAceCatalog.Aces.Count + 1 + 6 + 1 + 3);
        foreach (var achievement in Space)
        {
            var detail = achievement.GetAttribute<AchievementType, AchievementAttribute>();
            detail.IsActive.Should().BeTrue(achievement.ToString());
            detail.Name.Length.Should().BeLessThanOrEqualTo(24, "the notification window");
            detail.Description.Should().EndWith(".");
        }

        Space.Select(x => x.GetAttribute<AchievementType, AchievementAttribute>().Name).Should().OnlyHaveUniqueItems();
    }

    [Test]
    public void TierKills_MapEveryFactionTier()
    {
        Enumerable.Range(1, 6).Select(SpaceAchievementRules.TierKill).Should().Equal(
            AchievementType.SpaceKillTier1, AchievementType.SpaceKillTier2, AchievementType.SpaceKillTier3,
            AchievementType.SpaceKillTier4, AchievementType.SpaceKillTier5, AchievementType.SpaceKillTier6);
        SpaceAchievementRules.TierKill(0).Should().Be(AchievementType.Invalid);
        SpaceAchievementRules.TierKill(7).Should().Be(AchievementType.Invalid);
    }

    [Test]
    public void EverySiteType_HasItsOwnAchievement()
    {
        var types = Enum.GetValues<SignatureType>().Where(x => x != SignatureType.Invalid).ToList();
        types.Select(SpaceAchievementRules.Site).Should().OnlyHaveUniqueItems().And.NotContain(AchievementType.Invalid);
        SpaceAchievementRules.Site(SignatureType.Invalid).Should().Be(AchievementType.Invalid);
    }

    [TestCase(9999UL, 0)]
    [TestCase(10000UL, 1)]
    [TestCase(150000UL, 2)]
    [TestCase(1000000UL, 3)]
    public void TradeEarnings_ReachTheirMilestones(ulong total, int count)
    {
        SpaceAchievementRules.TradeEarnings(total).Should().Equal(SpaceAchievementRules.TradeMilestones.Take(count).Select(x => x.Achievement));
    }

    [Test]
    public void TradeEarnings_PersistOnTheAccount()
    {
        var account = new Account("CDKEY") { AchievementProgress = { TradeCreditsEarned = 12345 } };
        JsonConvert.DeserializeObject<Account>(JsonConvert.SerializeObject(account))!.AchievementProgress.TradeCreditsEarned
            .Should().Be(12345);
        JsonConvert.DeserializeObject<AchievementProgress>("{}")!.TradeCreditsEarned.Should().Be(0, "older accounts start at none");
    }

    [Test]
    public void NamedModules_EarnTheFittingAchievement()
    {
        var named = SWLOR.Game.Server.Feature.ShipModuleDefinition.RevampModuleCatalog.Steps.Where(x => x.Named).ToList();
        named.Should().NotBeEmpty();
        named.Should().OnlyContain(x => SpaceAchievementRules.IsNamedModule(x));
        SpaceAchievementRules.IsNamedModule(SWLOR.Game.Server.Feature.ShipModuleDefinition.RevampModuleCatalog.Steps.First(x => !x.Named)).Should().BeFalse();
        SpaceAchievementRules.IsNamedModule(null).Should().BeFalse();
    }

    [TestCase("Service/SpaceAchievements.cs", "[NWNEventHandler(ScriptName.OnCreatureDeathBefore)]")]
    [TestCase("Service/SpaceAchievements.cs", "Achievement.GiveAchievement(member, ace.Achievement);")]
    [TestCase("Service/SpaceAchievements.cs", "IsWildSpace(OBJECT_SELF)")]
    [TestCase("Service/SpaceSignatureJump.cs", "GrantSiteAchievement(player, signature.Type);")]
    [TestCase("Service/Trade.cs", "Space.RecordTradeEarnings(player, profit);")]
    [TestCase("Service/TradeFreight.cs", "Space.RecordTradeEarnings(player, result.Fee);")]
    [TestCase("Feature/GuiDefinition/ViewModel/ShipManagementViewModel.cs", "Space.GrantModuleFittedAchievement(Player, moduleDetails);")]
    public void Milestones_GrantTheirAchievements(string file, string expected)
    {
        var root = new DirectoryInfo(TestContext.CurrentContext.TestDirectory);
        while (!File.Exists(Path.Combine(root.FullName, "SWLOR.Game.Server.sln")))
            root = root.Parent!;
        File.ReadAllText(Path.Combine(root.FullName, "SWLOR.Game.Server", file)).Should().Contain(expected);
    }
}
